{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Across all four datasets, scale history embeddings by clamp((median_positive_training_count / item_count)^0.25, 0.5, 2.0). This deterministic feature may reduce domination by frequent items without adding learned parameters. Counts use training interactions only; padding remains zero. The buffer is checkpointed and restored by the existing predictor's dynamic model import. Candidate embeddings, GRU topology, readout, loss, optimizer and training settings remain fixed.",
      "edits": [
        {
          "find": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)
        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)
        self.register_buffer("input_frequency_scale", torch.ones(itemnum + 1))
        self.input_frequency_scale[0] = 0.0
        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:
        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:
        emb = self.dropout(
            self.item_emb(seq) * self.input_frequency_scale[seq].unsqueeze(-1)
        )"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):
        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):
        emb = self.dropout(
            self.item_emb(seq) * self.input_frequency_scale[seq].unsqueeze(-1)
        )"
        },
        {
          "find": "    ).to(device)
    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    ).to(device)
    counts = np.zeros(itemnum + 1, dtype=np.float64)
    for history in user_train.values():
        np.add.at(counts, np.asarray(history, dtype=np.int64), 1.0)
    counts[0] = 0.0
    observed = counts > 0
    median_count = float(np.median(counts[observed])) if observed.any() else 1.0
    scales = np.full(itemnum + 1, 2.0, dtype=np.float32)
    scales[observed] = np.clip(
        (median_count / counts[observed]) ** 0.25, 0.5, 2.0
    ).astype(np.float32)
    scales[0] = 0.0
    with torch.no_grad():
        model.input_frequency_scale.copy_(torch.from_numpy(scales).to(device))
    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
